// ROOM bath 2 (interior designer): en-suite for bedroom 2, inside the air box [29,2,14,30,4,16].
// Entry: the doorway (29,2..3,17) from bedroom 2 lands on the south row z=16. The north row z=14 holds the basin
// (under its mirror) and the WC against the north partition; the tub fills the south row, and the middle row z=15 is
// the clear lane between them. One standing lantern on the lane (on the smooth_quartz floor) lights the room; it sits
// beside the basin, the focal piece. The vault above z=14..19 is open, so nothing hangs from a ceiling here.
import { bath_fit, B } from "../vocab.mjs";

export function build(g) {
  // basin, mirror, WC (quartz_stairs facing south) and the tub: the shared bath fixture, 2 wide x 3 deep
  bath_fit(g, 29, 14);

  // the light: a standing lantern on the lane, at the basin's end, on the floor cell
  g.set(30, 2, 15, ...B.lantern(false));
}

